(window.__qhadithX=window.__qhadithX||{})[56]={"1":[{"c":"Sunan Abu Dawud","r":"Hadith 1401","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-1401","x":"Narrated Amr ibn al-'As:\n\nThe Prophet (ﷺ) taught me fifteen prostrations while reciting the Qur'an, including three in al-Mufassal and two in Surah al-Hajj. Abu Dawud said: Abu al-Darda' has reported eleven prostrations from the Prophet (ﷺ), but chain of this tradition is weak.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ الرَّحِيمِ بْنِ الْبَرْقِيِّ، حَدَّثَنَا ابْنُ أَبِي مَرْيَمَ، أَخْبَرَنَا نَافِعُ بْنُ يَزِيدَ، عَنِ الْحَارِثِ بْنِ سَعِيدٍ الْعُتَقِيِّ، عَنْ عَبْدِ اللَّهِ بْنِ مُنَيْنٍ، - مِنْ بَنِي عَبْدِ كُلاَلٍ - عَنْ عَمْرِو بْنِ الْعَاصِ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم أَقْرَأَهُ خَمْسَ عَشْرَةَ سَجْدَةً فِي الْقُرْآنِ مِنْهَا ثَلاَثٌ فِي الْمُفَصَّلِ وَفِي سُورَةِ الْحَجِّ سَجْدَتَانِ ‏.‏ قَالَ أَبُو دَاوُدَ رُوِيَ عَنْ أَبِي الدَّرْدَاءِ عَنِ النَّبِيِّ صلى الله عليه وسلم إِحْدَى عَشْرَةَ سَجْدَةً وَإِسْنَادُهُ وَاهٍ ‏.‏","v":[]}],"3":[{"c":"Muwatta Malik","r":"Book 29, Hadith 1178","u":"https://quranx.com/Hadith/Malik/In-Book/Book-29/Hadith-1178","x":"Yahya related to me from Malik from Hisham ibn Urwa that his father said that a man who pronounced a dhihar from his four wives in one statement, had only to do one kaffara. Yahya related the same as that to me from Malik from Rabia ibn Abi Abd ar-Rahman. Malik said, \"That is what is done among us. Allah, the Exalted said about the kaffara for pronouncing dhihar, 'It is to free a slave before they touch one another. If he does not find the means to do that, then fasting for two consecutive months before they touch one another. If he cannot do that, it is to feed sixty poor people. ' \" (Sura 58 ayats 4,5). Malik said that a man who pronounced dhihar from his wife on various occasions had only to do one kaffara. If he pronounced dhihar, and then did kaffara, and then pronounced dhihar after he had done the kaffara, he had to do kaffara again. Malik said, \"Some one who pronounces dhihar from his wife and then has intercourse with her before he has done kaffara, only has to do one kaffara. He must abstain from her until he does kaffara and ask forgiveness of Allah. That is the best of what I have heard. \" Malik said, \"It is the same with dhihar using any prohibited relations of fosterage and ancestry.\" Malik said, \"Women have no dhihar.\" Malik said that he had heard that the commentary on the word of Allah, the Blessed, the Exalted, \"Those of you who pronounce the dhihar about their wives, and then retract what they have said,\" (Sura 56 ayat 3), was that a man pronounced dhihar on his wife and then decided to keep her and have intercourse with her. If he decided on that, he must do kaffara. If he divorced her and did not decide to retract his dhihar of her and to keep her and have intercourse with her, there would be no kaffara incumbent on him. Maliksaid, \"If he marries her after that, he does not touch her until he has completed the kaffara of pronouncing dhihar.\" Malik said that if a man who pronounced dhihar from his slave-girl wanted to have intercourse with her, he had to do the kaffara of the dhihar before he could sleep with her. Malik said, \"There is no ila in a man's dhihar unless it is evident that he does not intend to retract his dhihar.\"","ar":"وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، أَنَّهُ قَالَ فِي رَجُلٍ تَظَاهَرَ مِنْ أَرْبَعَةِ نِسْوَةٍ لَهُ بِكَلِمَةٍ وَاحِدَةٍ إِنَّهُ لَيْسَ عَلَيْهِ إِلاَّ كَفَّارَةٌ وَاحِدَةٌ ‏.‏ وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ رَبِيعَةَ بْنِ أَبِي عَبْدِ الرَّحْمَنِ، مِثْلَ ذَلِكَ ‏.‏ قَالَ مَالِكٌ وَعَلَى ذَلِكَ الأَمْرُ عِنْدَنَا قَالَ اللَّهُ تَعَالَى فِي كَفَّارَةِ الْمُتَظَاهِرِ ‏{‏فَتَحْرِيرُ رَقَبَةٍ مِنْ قَبْلِ أَنْ يَتَمَاسَّا ‏}‏‏.‏ ‏{‏فَمَنْ لَمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ مِنْ قَبْلِ أَنْ يَتَمَاسَّا فَمَنْ لَمْ يَسْتَطِعْ فَإِطْعَامُ سِتِّينَ مِسْكِينًا‏}‏ ‏.‏ قَالَ مَالِكٌ فِي الرَّجُلِ يَتَظَاهَرُ مِنِ امْرَأَتِهِ فِي مَجَالِسَ مُتَفَرِّقَةٍ قَالَ لَيْسَ عَلَيْهِ إِلاَّ كَفَّارَةٌ وَاحِدَةٌ فَإِنْ تَظَاهَرَ ثُمَّ كَفَّرَ ثُمَّ تَظَاهَرَ بَعْدَ أَنْ يُكَفِّرَ فَعَلَيْهِ الْكَفَّارَةُ أَيْضًا ‏.‏ قَالَ مَالِكٌ وَمَنْ تَظَاهَرَ مِنِ امْرَأَتِهِ ثُمَّ مَسَّهَا قَبْلَ أَنْ يُكَفِّرَ لَيْسَ عَلَيْهِ إِلاَّ كَفَّارَةٌ وَاحِدَةٌ وَيَكُفُّ عَنْهَا حَتَّى يُكَفِّرَ وَلْيَسْتَغْفِرِ اللَّهَ وَذَلِكَ أَحْسَنُ مَا سَمِعْتُ ‏.‏ قَالَ مَالِكٌ وَالظِّهَارُ مِنْ ذَوَاتِ الْمَحَارِمِ مِنَ الرَّضَاعَةِ وَالنَّسَبِ سَوَاءٌ ‏.‏ قَالَ مَالِكٌ وَلَيْسَ عَلَى النِّسَاءِ ظِهَارٌ ‏.‏ قَالَ مَالِكٌ فِي قَوْلِ اللَّهِ تَبَارَكَ وَتَعَالَى ‏{‏وَالَّذِينَ يُظَاهِرُونَ مِنْ نِسَائِهِمْ ثُمَّ يَعُودُونَ لِمَا قَالُوا‏}‏‏.‏ قَالَ سَمِعْتُ أَنَّ تَفْسِيرَ ذَلِكَ أَنْ يَتَظَاهَرَ الرَّجُلُ مِنِ امْرَأَتِهِ ثُمَّ يُجْمِعَ عَلَى إِمْسَاكِهَا وَإِصَابَتِهَا فَإِنْ أَجْمَعَ عَلَى ذَلِكَ فَقَدْ وَجَبَتْ عَلَيْهِ الْكَفَّارَةُ وَإِنْ طَلَّقَهَا وَلَمْ يُجْمِعْ بَعْدَ تَظَاهُرِهِ مِنْهَا عَلَى إِمْسَاكِهَا وَإِصَابَتِهَا فَلاَ كَفَّارَةَ عَلَيْهِ ‏.‏ قَالَ مَالِكٌ فَإِنْ تَزَوَّجَهَا بَعْدَ ذَلِكَ لَمْ يَمَسَّهَا حَتَّى يُكَفِّرَ كَفَّارَةَ الْمُتَظَاهِرِ ‏.‏ قَالَ مَالِكٌ فِي الرَّجُلِ يَتَظَاهَرُ مِنْ أَمَتِهِ إِنَّهُ إِنْ أَرَادَ أَنْ يُصِيبَهَا فَعَلَيْهِ كَفَّارَةُ الظِّهَارِ قَبْلَ أَنْ يَطَأَهَا ‏.‏ قَالَ مَالِكٌ لاَ يَدْخُلُ عَلَى الرَّجُلِ إِيلاَءٌ فِي تَظَاهُرِهِ إِلاَّ أَنْ يَكُونَ مُضَارًّا لاَ يُرِيدُ أَنْ يَفِيءَ مِنْ تَظَاهُرِهِ ‏.","v":[]}],"4":[{"c":"Sahih Muslim","r":"Hadith 1479a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1479a","x":"'Umar b. al-Khattab (Allah be pleased with him) reported:\n\nWhen Allah's Apostle (ﷺ) kept himself away from his wives, I entered the mosque, and found people striking the ground with pebblesand saying: Allah's Messenger (ﷺ) has divorced his wives, and that was before they were commanded to observe seclusion 'Umar said to himself: I must find this (actual position) today. So I went to 'A'isha (Allah be pleased with her) and said (to her): Daughter of Abu Bakr, have you gone to the extent of giving trouble to Allah's Messenger (ﷺ)? Thereupon she said: Son of Khattab, you have nothing to do with me, and I have nothing to do with you. You should look to your own receptacle. He ('Umar) said: I visited Hafsa daughter of 'Umar, and said to her: Hafsa, the (news) has reached me that you cause Allah's Messenger (ﷺ) trouble. You know that Allah's Messenger (ﷺ) does not love you, and had I not been (your father) he would have divorced you. (On hearing this) she wept bitterly. I said to her: Where is Allah's Messenger (ﷺ)? Shesaid: He is in the attic room. I went in and found Rabah, the servant of Allah's Messenger (ﷺ), sitting on the thresholds of the window dangling his feet on the hollow wood of the date-palm with the help of which Allah's Messenger (ﷺ) climbed (to the apartment) and came down. I cried: 0 Rabah, seek permission for me from Allah's Messenger (way peace be upon him). Rabah cast a glance at the apartment and then looked toward me but said nothing. I again said: Rabah, seek permission for me from Allah's Messenger (ﷺ). Rabah looked towards the apartment and then cast a glance at me, but said nothig. I then raised my voice and said: 0 Rabah, seek permission for me from Allah's Messenger (ﷺ). I think that Allah's Messenger (ﷺ) is under the impression that I have come for the sake of Hafsa. By Allah, if Allah's Messenger (ﷺ) would command me to strike her neck, I would certainly strike her neck. I raised my voice and he pointed me to climb up (and get into his apartment). I visited Allah's Messenger (ﷺ), and he was lying on a mat. I sat down and he drew up his lower garment over him and he had nothing (else) over him, and that the mat had left its marks on his sides. I looked with my eyes in the store room of Allah's Messenger (ﷺ). I found only a handful of barley equal to one sa' and an equal quantity of the leaves of Mimosa Flava placed in the nook of the cell, and a semi-tanned leather bag hanging (in one side), and I was moved to tears (on seeing this extremely austere living of the Holy Piophet), and he said: Ibn Khattab, what wakes you weep? I said: Apostle of Allah, why should I not shed tears? This mat has left its marks on your sides and I do not see in your store room (except these few things) that I have seen; Ceasar and Closroes are leading their lives in plenty whereas you are Allah's Messenger. His chosen one, and that is your store! He said: Ibn Khattab, aren't you satisfied that for us (there should be the prosperity) of the Hereafter, and for them (there should be the prosperity of) this world? I said: Yes. And as I had entered I had seen the signs of anger on his face, and I therefore, said: Messenger of Allah, what trouble do you feel from your wives, and if youhave divorced them, verily Allah is with you, His angels, Gabriel, Mika'il, I and Abu Bakr and the believers are with you. And seldom I talked and (which I uttered on that day) I hoped that Allah would testify to my words that I uttered. And so the verse of option (Ayat al-Takhyir) was revealed. Maybe his Lord, if he divorce you, will give him in your place wives better than you...\" (Ixv. 5). And if you back up one another against him, then surely Allah is his Patron, and Gabriel and the righteous believers, and the angels after that are the aidera (lvi. 4). And it was 'A'isha, daughter of Abu Bakr, and Hafsa who had prevailed upon all the wives of Allah's Prophet (way peace be upon him) for (pressing them for mote money). I said: Messenger of Allah, have you divorced them? He said: No. I said: Messenger of Allah, I entered the mosque and found the Muslims playing with pebbles (absorbed in thought) and saying: Allah's Messenger has divorced his wives. Should I get down and inform there that you have not divorced them? He said: Yes, if you so like. And I went on talking to him until I (found) the signs of anger disappeared on his face and (his seriousness was changed to a happy mood and as a result thereof) his face had the natural tranquillity upon it and he laughed and his teeth were the most charming (among the teeth) of all people. Then Allah's Apostle (ﷺ) climbed down and I also climbed down and catching hold of the wood of the palm-tree and Allah's Messenger (ﷺ) came down (with such ease) as if he was walking on the ground, not touching anything with his hand (to get support). I said: Messenger of Allah, you remained in your apartment for twenty-nine days. He said: (At times) the month consists of twenty-nine days. I stood at the door of the mosque and I called out at the top of my voice: The Messenger of Allah (ﷺ) has not divorced his wives (and it was on this occasion that this) verse was revealed:\" And if any matter pertaining to peace or alarm comes within their ken, they broadcast it; whereas, if they would refer it to the Apostle and those who have been entrusted with authority amongst them, those of them who are engaged in obtaining intelligence would indeed know (what to do with) it\" (iv 83). And it was I who understood this matter, and Allah revealed the verse pertaining to option (given to the Prophet (may peace be upon him in regard to the retaining or divorcing of his wives).","ar":"حَدَّثَنِي زُهَيْرُ بْنُ حَرْبٍ، حَدَّثَنَا عُمَرُ بْنُ يُونُسَ الْحَنَفِيُّ، حَدَّثَنَا عِكْرِمَةُ بْنُ عَمَّارٍ، عَنْ سِمَاكٍ أَبِي زُمَيْلٍ، حَدَّثَنِي عَبْدُ اللَّهِ بْنُ عَبَّاسٍ، حَدَّثَنِي عُمَرُ بْنُ الْخَطَّابِ، قَالَ لَمَّا اعْتَزَلَ نَبِيُّ اللَّهِ صلى الله عليه وسلم نِسَاءَهُ - قَالَ - دَخَلْتُ الْمَسْجِدَ فَإِذَا النَّاسُ يَنْكُتُونَ بِالْحَصَى وَيَقُولُونَ طَلَّقَ رَسُولُ اللَّهِ صلى الله عليه وسلم نِسَاءَهُ وَذَلِكَ قَبْلَ أَنْ يُؤْمَرْنَ بِالْحِجَابِ فَقَالَ عُمَرُ فَقُلْتُ لأَعْلَمَنَّ ذَلِكَ الْيَوْمَ قَالَ فَدَخَلْتُ عَلَى عَائِشَةَ فَقُلْتُ يَا بِنْتَ أَبِي بَكْرٍ أَقَدْ بَلَغَ مِنْ شَأْنِكِ أَنْ تُؤْذِي رَسُولَ اللَّهِ صلى الله عليه وسلم فَقَالَتْ مَا لِي وَمَا لَكَ يَا ابْنَ الْخَطَّابِ عَلَيْكَ بِعَيْبَتِكَ ‏.‏ قَالَ فَدَخَلْتُ عَلَى حَفْصَةَ بِنْتِ عُمَرَ فَقُلْتُ لَهَا يَا حَفْصَةُ أَقَدْ بَلَغَ مِنْ شَأْنِكِ أَنْ تُؤْذِي رَسُولَ اللَّهِ صلى الله عليه وسلم وَاللَّهِ لَقَدْ عَلِمْتِ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم لاَ يُحِبُّكِ ‏.‏ وَلَوْلاَ أَنَا لَطَلَّقَكِ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏.‏ فَبَكَتْ أَشَدَّ الْبُكَاءِ فَقُلْتُ لَهَا أَيْنَ رَسُولُ اللَّهِ صلى الله عليه وسلم قَالَتْ هُوَ فِي خِزَانَتِهِ فِي الْمَشْرُبَةِ ‏.‏ فَدَخَلْتُ فَإِذَا أَنَا بِرَبَاحٍ غُلاَمِ رَسُولِ اللَّهِ صلى الله عليه وسلم قَاعِدًا عَلَى أُسْكُفَّةِ الْمَشْرُبَةِ مُدَلٍّ رِجْلَيْهِ عَلَى نَقِيرٍ مِنْ خَشَبٍ وَهُوَ جِذْعٌ يَرْقَى عَلَيْهِ رَسُولُ اللَّهِ صلى الله عليه وسلم وَيَنْحَدِرُ فَنَادَيْتُ يَا رَبَاحُ اسْتَأْذِنْ لِي عِنْدَكَ عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم ‏.‏ فَنَظَرَ رَبَاحٌ إِلَى الْغُرْفَةِ ثُمَّ نَظَرَ إِلَىَّ فَلَمْ يَقُلْ شَيْئًا ثُمَّ قُلْتُ يَا رَبَاحُ اسْتَأْذِنْ لِي عِنْدَكَ عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم ‏.‏ فَنَظَرَ رَبَاحٌ إِلَى الْغُرْفَةِ ثُمَّ نَظَرَ إِلَىَّ فَلَمْ يَقُلْ شَيْئًا ثُمَّ رَفَعْتُ صَوْتِي فَقُلْتُ يَا رَبَاحُ اسْتَأْذِنْ لِي عِنْدَكَ عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَإِنِّي أَظُنُّ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم ظَنَّ أَنِّي جِئْتُ مِنْ أَجْلِ حَفْصَةَ وَاللَّهِ لَئِنْ أَمَرَنِي رَسُولُ اللَّهِ صلى الله عليه وسلم بِضَرْبِ عُنُقِهَا لأَضْرِبَنَّ عُنُقَهَا ‏.‏ وَرَفَعْتُ صَوْتِي فَأَوْمَأَ إِلَىَّ أَنِ ارْقَهْ فَدَخَلْتُ عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم وَهُوَ مُضْطَجِعٌ عَلَى حَصِيرٍ فَجَلَسْتُ فَأَدْنَى عَلَيْهِ إِزَارَهُ وَلَيْسَ عَلَيْهِ غَيْرُهُ وَإِذَا الْحَصِيرُ قَدْ أَثَّرَ فِي جَنْبِهِ فَنَظَرْتُ بِبَصَرِي فِي خِزَانَةِ رَسُولِ اللَّهِ صلى الله عليه وسلم فَإِذَا أَنَا بِقَبْضَةٍ مِنْ شَعِيرٍ نَحْوِ الصَّاعِ وَمِثْلِهَا قَرَظًا فِي نَاحِيَةِ الْغُرْفَةِ وَإِذَا أَفِيقٌ مُعَلَّقٌ - قَالَ - فَابْتَدَرَتْ عَيْنَاىَ قَالَ ‏\"‏ مَا يُبْكِيكَ يَا ابْنَ الْخَطَّابِ ‏\"‏ ‏.‏ قُلْتُ يَا نَبِيَّ اللَّهِ وَمَا لِي لاَ أَبْكِي وَهَذَا الْحَصِيرُ قَدْ أَثَّرَ فِي جَنْبِكَ وَهَذِهِ خِزَانَتُكَ لاَ أَرَى فِيهَا إِلاَّ مَا أَرَى وَذَاكَ قَيْصَرُ وَكِسْرَى فِي الثِّمَارِ وَالأَنْهَارِ وَأَنْتَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَصَفْوَتُهُ وَهَذِهِ خِزَانَتُكَ ‏.‏ فَقَالَ ‏\"‏ يَا ابْنَ الْخَطَّابِ أَلاَ تَرْضَى أَنْ تَكُونَ لَنَا الآخِرَةُ وَلَهُمُ الدُّنْيَا ‏\"‏ ‏.‏ قُلْتُ بَلَى - قَالَ - وَدَخَلْتُ عَلَيْهِ حِينَ دَخَلْتُ وَأَنَا أَرَى فِي وَجْهِهِ الْغَضَبَ فَقُلْتُ يَا رَسُولَ اللَّهِ مَا يَشُقُّ عَلَيْكَ مِنْ شَأْنِ النِّسَاءِ فَإِنْ كُنْتَ طَلَّقْتَهُنَّ فَإِنَّ اللَّهَ مَعَكَ وَمَلاَئِكَتَهُ وَجِبْرِيلَ وَمِيكَائِيلَ وَأَنَا وَأَبُو بَكْرٍ وَالْمُؤْمِنُونَ مَعَكَ وَقَلَّمَا تَكَلَّمْتُ وَأَحْمَدُ اللَّهَ بِكَلاَمٍ إِلاَّ رَجَوْتُ أَنْ يَكُونَ اللَّهُ يُصَدِّقُ قَوْلِي الَّذِي أَقُولُ وَنَزَلَتْ هَذِهِ الآيَةُ آيَةُ التَّخْيِيرِ ‏{‏ عَسَى رَبُّهُ إِنْ طَلَّقَكُنَّ أَنْ يُبْدِلَهُ أَزْوَاجًا خَيْرًا مِنْكُنَّ‏}‏ ‏{‏ وَإِنْ تَظَاهَرَا عَلَيْهِ فَإِنَّ اللَّهَ هُوَ مَوْلاَهُ وَجِبْرِيلُ وَصَالِحُ الْمُؤْمِنِينَ وَالْمَلاَئِكَةُ بَعْدَ ذَلِكَ ظَهِيرٌ‏}‏ وَكَانَتْ عَائِشَةُ بِنْتُ أَبِي بَكْرٍ وَحَفْصَةُ تَظَاهَرَانِ عَلَى سَائِرِ نِسَاءِ النَّبِيِّ صلى الله عليه وسلم فَقُلْتُ يَا رَسُولَ اللَّهِ أَطَلَّقْتَهُنَّ قَالَ ‏\"‏ لاَ ‏\"‏ ‏.‏ قُلْتُ يَا رَسُولَ اللَّهِ إِنِّي دَخَلْتُ الْمَسْجِدَ وَالْمُسْلِمُونَ يَنْكُتُونَ بِالْحَصَى يَقُولُونَ طَلَّقَ رَسُولُ اللَّهِ صلى الله عليه وسلم نِسَاءَهُ أَفَأَنْزِلُ فَأُخْبِرَهُمْ أَنَّكَ لَمْ تُطَلِّقْهُنَّ قَالَ ‏\"‏ نَعَمْ إِنْ شِئْتَ ‏\"‏ ‏.‏ فَلَمْ أَزَلْ أُحَدِّثُهُ حَتَّى تَحَسَّرَ الْغَضَبُ عَنْ وَجْهِهِ وَحَتَّى كَشَرَ فَضَحِكَ وَكَانَ مِنْ أَحْسَنِ النَّاسِ ثَغْرًا ثُمَّ نَزَلَ نَبِيُّ اللَّهِ صلى الله عليه وسلم وَنَزَلْتُ فَنَزَلْتُ أَتَشَبَّثُ بِالْجِذْعِ وَنَزَلَ رَسُولُ اللَّهِ صلى الله عليه وسلم كَأَنَّمَا يَمْشِي عَلَى الأَرْضِ مَا يَمَسُّهُ بِيَدِهِ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّمَا كُنْتَ فِي الْغُرْفَةِ تِسْعَةً وَعِشْرِينَ ‏.‏ قَالَ ‏\"‏ إِنَّ الشَّهْرَ يَكُونُ تِسْعًا وَعِشْرِينَ ‏\"‏ ‏.‏ فقُمْتُ عَلَى بَابِ الْمَسْجِدِ فَنَادَيْتُ بِأَعْلَى صَوْتِي لَمْ يُطَلِّقْ رَسُولُ اللَّهِ صلى الله عليه وسلم نِسَاءَهُ ‏.‏ وَنَزَلَتْ هَذِهِ الآيَةُ ‏{‏ وَإِذَا جَاءَهُمْ أَمْرٌ مِنَ الأَمْنِ أَوِ الْخَوْفِ أَذَاعُوا بِهِ وَلَوْ رَدُّوهُ إِلَى الرَّسُولِ وَإِلَى أُولِي الأَمْرِ مِنْهُمْ لَعَلِمَهُ الَّذِينَ يَسْتَنْبِطُونَهُ مِنْهُمْ‏}‏ فَكُنْتُ أَنَا اسْتَنْبَطْتُ ذَلِكَ الأَمْرَ وَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ آيَةَ التَّخْيِيرِ ‏.‏","v":[]}],"30":[{"c":"Sunan Ibn Majah","r":"Volume 5, Book 37, Hadith 4335","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-5/Book-37/Hadith-4335","x":"It was narrated from Abu Hurairah that the Messenger of Allah (ﷺ) said:\n\n\"In Paradise there is a tree under whose shade a rider could travel for one hundred years and never leave it.\" \"Recite, if you wish: 'And in shade long-extended (56:30).'\"","ar":"حَدَّثَنَا أَبُو عُمَرَ الضَّرِيرُ، حَدَّثَنَا عَبْدُ الرَّحْمَنِ بْنُ عُثْمَانَ، عَنْ مُحَمَّدِ بْنِ عَمْرٍو، عَنْ أَبِي سَلَمَةَ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ ‏\"‏ إِنَّ فِي الْجَنَّةِ شَجَرَةً يَسِيرُ الرَّاكِبُ فِي ظِلِّهَا مِائَةَ سَنَةٍ لاَ يَقْطَعُهَا ‏\"‏ ‏.‏ وَاقْرَءُوا إِنْ شِئْتُمْ ‏{وَظِلٍّ مَمْدُودٍ * وَمَاءٍ مَسْكُوبٍ ‏)‏ ‏.‏","v":[]}],"34":[{"c":"Jami` at-Tirmidhi","r":"Volume 4, Book 36, Hadith 2540","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-4/Book-36/Hadith-2540","x":"Abu Sa'eed narrated concerning His (Allah's) statement \"And couches, elevated...\" (Al Wa'qiah 56:34) that the Prophet (s.a.w) said:\n\n\"Their elevation is indeed like what is between the heavens and the earth, a distance of five-hundred years.\"","ar":"حَدَّثَنَا أَبُو كُرَيْبٍ، حَدَّثَنَا رِشْدِينُ بْنُ سَعْدٍ، عَنْ عَمْرِو بْنِ الْحَارِثِ، عَنْ دَرَّاجٍ أَبِي السَّمْحِ، عَنْ أَبِي الْهَيْثَمِ، عَنْ أَبِي سَعِيدٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم فِي قَوْلِهِ‏:‏ ‏(‏وَفُرُشٍ مَرْفُوعَةٍ ‏)‏ قَالَ ‏\"‏ ارْتِفَاعُهَا لَكَمَا بَيْنَ السَّمَاءِ وَالأَرْضِ مَسِيرَةَ خَمْسِمِائَةِ سَنَةٍ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ لاَ نَعْرِفُهُ إِلاَّ مِنْ حَدِيثِ رِشْدِينَ بْنِ سَعْدٍ ‏.‏ وَقَالَ بَعْضُ أَهْلِ الْعِلْمِ فِي تَفْسِيرِ هَذَا الْحَدِيثِ إِنَّ مَعْنَاهُ الْفُرُشَ فِي الدَّرَجَاتِ وَبَيْنَ الدَّرَجَاتِ كَمَا بَيْنَ السَّمَاءِ وَالأَرْضِ ‏.‏","v":[]}],"35":[{"c":"Shama'il Muhammadiyah","r":"Hadith 239","u":"https://quranx.com/Hadith/Shamail/Reference/Hadith-239","x":"Al-Hasan Al-Basri said:\n\n\"An old woman came to the Prophet (Allah bless him and give him peace) and said: 'O Messenger of Allah, beseech Allah to let me enter the Garden of Paradise!' He replied: 'O Mother of So-and-so, no old woman will enter the Garden of Paradise!' She turned away weeping, so he said: 'Tell her that she will not enter it as an old woman, for Allah says: ‘We have created them a new creation, and made them virgins, loving, equal in age [inna ansha’na-hunna insha’a: fa-ja'alna-hunna abkara 'uruban atraba].’\" (Al-Qur'an; 56:35-37)","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، قَالَ‏:‏ حَدَّثَنَا مُصْعَبُ بْنُ الْمِقْدَامِ، قَالَ‏:‏ حَدَّثَنَا الْمُبَارِكُ بْنُ فَضَالَةَ، عَنِ الْحَسَنِ، قَالَ‏:‏ أَتَتْ عَجُوزٌ إِلَى النَّبِيِّ صلى الله عليه وسلم، فَقَالَتْ‏:‏ يَا رَسُولَ اللهِ، ادْعُ اللَّهَ أَنْ يُدْخِلَنِي الْجَنَّةَ، فَقَالَ‏:‏ يَا أُمَّ فُلانٍ، إِنَّ الْجَنَّةَ لا تَدْخُلُهَا عَجُوزٌ، قَالَ‏:‏ فَوَلَّتْ تَبْكِي، فَقَالَ‏:‏ أَخْبِرُوهَا أَنَّهَا لا تَدْخُلُهَا وَهِيَ عَجُوزٌ إِنَّ اللَّهَ تَعَالَى، يَقُولُ‏:‏ إِنَّا أَنْشَأْنَاهُنَّ إِنْشَاءً، فَجَعَلْنَاهُنَّ أَبْكَارًا، عُرُبًا أَتْرَابًا‏.‏","v":[]}],"36":[{"c":"Shama'il Muhammadiyah","r":"Hadith 239","u":"https://quranx.com/Hadith/Shamail/Reference/Hadith-239","x":"Al-Hasan Al-Basri said:\n\n\"An old woman came to the Prophet (Allah bless him and give him peace) and said: 'O Messenger of Allah, beseech Allah to let me enter the Garden of Paradise!' He replied: 'O Mother of So-and-so, no old woman will enter the Garden of Paradise!' She turned away weeping, so he said: 'Tell her that she will not enter it as an old woman, for Allah says: ‘We have created them a new creation, and made them virgins, loving, equal in age [inna ansha’na-hunna insha’a: fa-ja'alna-hunna abkara 'uruban atraba].’\" (Al-Qur'an; 56:35-37)","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، قَالَ‏:‏ حَدَّثَنَا مُصْعَبُ بْنُ الْمِقْدَامِ، قَالَ‏:‏ حَدَّثَنَا الْمُبَارِكُ بْنُ فَضَالَةَ، عَنِ الْحَسَنِ، قَالَ‏:‏ أَتَتْ عَجُوزٌ إِلَى النَّبِيِّ صلى الله عليه وسلم، فَقَالَتْ‏:‏ يَا رَسُولَ اللهِ، ادْعُ اللَّهَ أَنْ يُدْخِلَنِي الْجَنَّةَ، فَقَالَ‏:‏ يَا أُمَّ فُلانٍ، إِنَّ الْجَنَّةَ لا تَدْخُلُهَا عَجُوزٌ، قَالَ‏:‏ فَوَلَّتْ تَبْكِي، فَقَالَ‏:‏ أَخْبِرُوهَا أَنَّهَا لا تَدْخُلُهَا وَهِيَ عَجُوزٌ إِنَّ اللَّهَ تَعَالَى، يَقُولُ‏:‏ إِنَّا أَنْشَأْنَاهُنَّ إِنْشَاءً، فَجَعَلْنَاهُنَّ أَبْكَارًا، عُرُبًا أَتْرَابًا‏.‏","v":[]}],"37":[{"c":"Shama'il Muhammadiyah","r":"Hadith 239","u":"https://quranx.com/Hadith/Shamail/Reference/Hadith-239","x":"Al-Hasan Al-Basri said:\n\n\"An old woman came to the Prophet (Allah bless him and give him peace) and said: 'O Messenger of Allah, beseech Allah to let me enter the Garden of Paradise!' He replied: 'O Mother of So-and-so, no old woman will enter the Garden of Paradise!' She turned away weeping, so he said: 'Tell her that she will not enter it as an old woman, for Allah says: ‘We have created them a new creation, and made them virgins, loving, equal in age [inna ansha’na-hunna insha’a: fa-ja'alna-hunna abkara 'uruban atraba].’\" (Al-Qur'an; 56:35-37)","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، قَالَ‏:‏ حَدَّثَنَا مُصْعَبُ بْنُ الْمِقْدَامِ، قَالَ‏:‏ حَدَّثَنَا الْمُبَارِكُ بْنُ فَضَالَةَ، عَنِ الْحَسَنِ، قَالَ‏:‏ أَتَتْ عَجُوزٌ إِلَى النَّبِيِّ صلى الله عليه وسلم، فَقَالَتْ‏:‏ يَا رَسُولَ اللهِ، ادْعُ اللَّهَ أَنْ يُدْخِلَنِي الْجَنَّةَ، فَقَالَ‏:‏ يَا أُمَّ فُلانٍ، إِنَّ الْجَنَّةَ لا تَدْخُلُهَا عَجُوزٌ، قَالَ‏:‏ فَوَلَّتْ تَبْكِي، فَقَالَ‏:‏ أَخْبِرُوهَا أَنَّهَا لا تَدْخُلُهَا وَهِيَ عَجُوزٌ إِنَّ اللَّهَ تَعَالَى، يَقُولُ‏:‏ إِنَّا أَنْشَأْنَاهُنَّ إِنْشَاءً، فَجَعَلْنَاهُنَّ أَبْكَارًا، عُرُبًا أَتْرَابًا‏.‏","v":[]}],"89":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 43, Hadith 2938","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-43/Hadith-2938","x":"Narrated 'Aishah:\n\nthat the Prophet (ﷺ) would recite: \"Furuhun Wa Raihanun Wa Jannatu Na'im (56:89)\"","ar":"حَدَّثَنَا بِشْرُ بْنُ هِلاَلٍ الصَّوَّافُ الْبَصْرِيُّ ، قَالَ حَدَّثَنَا جَعْفَرُ بْنُ سُلَيْمَانَ الضُّبَعِيُّ، عَنْ هَارُونَ الأَعْوَرِ، عَنْ بُدَيْلِ بْنِ مَيْسَرَةَ، عَنْ عَبْدِ اللَّهِ بْنِ شَقِيقٍ، عَنْ عَائِشَةَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم كَانَ يَقْرَأُ ‏(‏فَرُوحٌ وَ رَيْحَانٌ وَ جَنَّةُ نَعِيمٍ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ لاَ نَعْرِفُهُ إِلاَّ مِنْ حَدِيثِ هَارُونَ الأَعْوَرِ ‏.‏","v":[]}]};